DROP TABLE IF EXISTS `fa_account`;
CREATE TABLE `fa_account` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `currency` varchar(10) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'JPY' COMMENT '币种:JPY=日元,USD=美元,USDT=泰达币',
  `balance` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '可用余额',
  `frozen` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '冻结余额',
  `total_deposit` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '累计充值',
  `total_withdraw` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '累计提现',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_currency` (`user_id`,`currency`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户资金账户表';


