DROP TABLE IF EXISTS `fa_follow`;
CREATE TABLE `fa_follow` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `trader_id` int unsigned NOT NULL DEFAULT '0' COMMENT '交易员ID',
  `amount` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '跟单金额',
  `profit` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '跟单收益',
  `status` enum('following','paused','stopped') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'following' COMMENT '状态:following=跟随中,paused=暂停,stopped=已停止',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_trader` (`user_id`,`trader_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='跟单表';


DROP TABLE IF EXISTS `fa_ipo`;
CREATE TABLE `fa_ipo` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `code` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证券代码',
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证券名称',
  `market` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'TSE' COMMENT '上市市场',
  `issue_price` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '发行价',
  `total_shares` bigint NOT NULL DEFAULT '0' COMMENT '发行总量',
  `min_quantity` int unsigned NOT NULL DEFAULT '100' COMMENT '最小认购数量',
  `max_quantity` int unsigned NOT NULL DEFAULT '0' COMMENT '最大认购数量',
  `start_time` bigint DEFAULT NULL COMMENT '认购开始时间',
  `end_time` bigint DEFAULT NULL COMMENT '认购结束时间',
  `list_date` bigint DEFAULT NULL COMMENT '上市日期',
  `intro` text COLLATE utf8mb4_general_ci COMMENT '公司简介',
  `status` enum('upcoming','ongoing','closed','listed') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'ongoing' COMMENT '状态:upcoming=待开始,ongoing=认购中,closed=已截止,listed=已上市',
  `weigh` int NOT NULL DEFAULT '0' COMMENT '权重',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='新股发行表';


DROP TABLE IF EXISTS `fa_ipo_apply`;
CREATE TABLE `fa_ipo_apply` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `apply_no` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '认购单号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `ipo_id` int unsigned NOT NULL DEFAULT '0' COMMENT '新股ID',
  `code` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证券代码',
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证券名称',
  `quantity` int unsigned NOT NULL DEFAULT '0' COMMENT '认购数量',
  `price` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '发行价',
  `amount` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '认购金额',
  `allotment` int unsigned NOT NULL DEFAULT '0' COMMENT '中签数量',
  `status` enum('pending','won','partial','lost','canceled') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT '状态:pending=待公布,won=已中签,partial=部分中签,lost=未中签,canceled=已撤销',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  `checktime` bigint DEFAULT NULL COMMENT '公布时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_apply_no` (`apply_no`),
  KEY `idx_user` (`user_id`),
  KEY `idx_ipo` (`ipo_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='新股认购记录表';


DROP TABLE IF EXISTS `fa_order`;
CREATE TABLE `fa_order` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '委托单号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `stock_id` int unsigned NOT NULL DEFAULT '0' COMMENT '证券ID',
  `code` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证券代码',
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证券名称',
  `currency` varchar(10) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'JPY' COMMENT '计价币种',
  `side` enum('buy','sell') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'buy' COMMENT '方向:buy=买入,sell=卖出',
  `type` enum('market','limit') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'limit' COMMENT '类型:market=市价,limit=限价',
  `price` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '委托价',
  `quantity` int unsigned NOT NULL DEFAULT '0' COMMENT '委托数量',
  `amount` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '委托金额',
  `filled_quantity` int unsigned NOT NULL DEFAULT '0' COMMENT '已成交数量',
  `filled_amount` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '已成交金额',
  `fee` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '手续费',
  `status` enum('pending','partial','filled','canceled','rejected') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT '状态:pending=待成交,partial=部分成交,filled=已成交,canceled=已撤单,rejected=已拒绝',
  `remark` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  `finishtime` bigint DEFAULT NULL COMMENT '完成时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_user` (`user_id`),
  KEY `idx_stock` (`stock_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='委托订单表';


DROP TABLE IF EXISTS `fa_position`;
CREATE TABLE `fa_position` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `stock_id` int unsigned NOT NULL DEFAULT '0' COMMENT '证券ID',
  `code` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证券代码',
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证券名称',
  `currency` varchar(10) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'JPY' COMMENT '计价币种',
  `quantity` int unsigned NOT NULL DEFAULT '0' COMMENT '持仓数量',
  `available` int unsigned NOT NULL DEFAULT '0' COMMENT '可卖数量',
  `cost_price` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '成本价',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_stock` (`user_id`,`stock_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='持仓表';


DROP TABLE IF EXISTS `fa_sms`;
CREATE TABLE `fa_sms` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `event` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '事件',
  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '手机号',
  `code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '验证码',
  `times` int unsigned NOT NULL DEFAULT '0' COMMENT '验证次数',
  `ip` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT 'IP',
  `createtime` bigint unsigned DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='短信验证码表';


DROP TABLE IF EXISTS `fa_stock`;
CREATE TABLE `fa_stock` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `code` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证券代码',
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证券名称',
  `market` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'TSE' COMMENT '所属市场:TSE=东京证券交易所,NY=纽交所,NASDAQ=纳斯达克,CRYPTO=加密货币',
  `type` enum('stock','crypto','index','sector') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'stock' COMMENT '类型:stock=股票,crypto=加密货币,index=指数,sector=板块',
  `currency` varchar(10) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'JPY' COMMENT '计价币种:JPY=日元,USD=美元',
  `price` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '最新价',
  `prev_close` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '昨收价',
  `open` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '今开',
  `high` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '最高',
  `low` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '最低',
  `change_amount` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '涨跌额',
  `change_rate` decimal(10,4) NOT NULL DEFAULT '0.0000' COMMENT '涨跌幅(%)',
  `volume` bigint NOT NULL DEFAULT '0' COMMENT '成交量(股)',
  `turnover` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '成交额',
  `total_shares` bigint NOT NULL DEFAULT '0' COMMENT '总股本',
  `lot_size` int unsigned NOT NULL DEFAULT '100' COMMENT '每手股数',
  `image` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图标',
  `is_hot` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否热门:0=否,1=是',
  `weigh` int NOT NULL DEFAULT '0' COMMENT '权重(排序)',
  `status` enum('normal','suspended','hidden') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'normal' COMMENT '状态:normal=交易中,suspended=停牌,hidden=隐藏',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  `sector` varchar(50) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '所属行业/板块',
  `source` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '数据来源:twelvedata/coingecko/manual',
  `symbol` varchar(50) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '数据源代码',
  `market_cap` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '总市值',
  `pe_ratio` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '市盈率PE',
  `pb_ratio` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '市净率PB',
  `dividend_yield` decimal(10,4) NOT NULL DEFAULT '0.0000' COMMENT '股息率(%)',
  `turnover_rate` decimal(10,4) NOT NULL DEFAULT '0.0000' COMMENT '换手率(%)',
  `amplitude` decimal(10,4) NOT NULL DEFAULT '0.0000' COMMENT '振幅(%)',
  `high_52w` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '52周最高',
  `low_52w` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '52周最低',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_market` (`market`)
) ENGINE=InnoDB AUTO_INCREMENT=258 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='证券标的表';


DROP TABLE IF EXISTS `fa_stock_favorite`;
CREATE TABLE `fa_stock_favorite` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `stock_id` int unsigned NOT NULL DEFAULT '0' COMMENT '证券ID',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_stock` (`user_id`,`stock_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='自选(收藏)表';


DROP TABLE IF EXISTS `fa_stock_kline`;
CREATE TABLE `fa_stock_kline` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `stock_id` int unsigned NOT NULL DEFAULT '0' COMMENT '证券ID',
  `code` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证券代码',
  `period` varchar(10) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1d' COMMENT '周期:1m=1分钟,5m,15m,1h,1d=日线,1w=周线',
  `time` bigint NOT NULL DEFAULT '0' COMMENT 'K线时间',
  `open` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '开盘',
  `high` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '最高',
  `low` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '最低',
  `close` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '收盘',
  `volume` bigint NOT NULL DEFAULT '0' COMMENT '成交量',
  `date` varchar(10) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '交易日期',
  `createtime` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_stock_period` (`stock_id`,`period`),
  KEY `idx_code_period_time` (`code`,`period`,`time`)
) ENGINE=InnoDB AUTO_INCREMENT=2994 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='K线行情表';


DROP TABLE IF EXISTS `fa_support`;
CREATE TABLE `fa_support` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type` enum('faq','notice') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'faq' COMMENT '类型:faq=常见问题,notice=公告',
  `title` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题',
  `content` text COLLATE utf8mb4_general_ci COMMENT '内容',
  `lang` varchar(10) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'ja' COMMENT '语言:ja=日文,zh=中文,en=英文',
  `weigh` int NOT NULL DEFAULT '0' COMMENT '权重',
  `status` enum('normal','hidden') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'normal' COMMENT '状态',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='客服帮助/公告表';


DROP TABLE IF EXISTS `fa_test`;
CREATE TABLE `fa_test` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user_id` int DEFAULT '0' COMMENT '会员ID',
  `admin_id` int DEFAULT '0' COMMENT '管理员ID',
  `category_id` int unsigned DEFAULT '0' COMMENT '分类ID(单选)',
  `category_ids` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '分类ID(多选)',
  `tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '标签',
  `week` enum('monday','tuesday','wednesday') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '星期(单选):monday=星期一,tuesday=星期二,wednesday=星期三',
  `flag` set('hot','index','recommend') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '标志(多选):hot=热门,index=首页,recommend=推荐',
  `genderdata` enum('male','female') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'male' COMMENT '性别(单选):male=男,female=女',
  `hobbydata` set('music','reading','swimming') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '爱好(多选):music=音乐,reading=读书,swimming=游泳',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '内容',
  `image` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '图片',
  `images` varchar(1500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '图片组',
  `attachfile` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '附件',
  `keywords` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '关键字',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '描述',
  `city` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '省市',
  `array` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '数组:value=值',
  `json` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '配置:key=名称,value=值',
  `multiplejson` varchar(1500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '二维数组:title=标题,intro=介绍,author=作者,age=年龄',
  `price` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '价格',
  `views` int unsigned DEFAULT '0' COMMENT '点击',
  `workrange` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '时间区间',
  `startdate` date DEFAULT NULL COMMENT '开始日期',
  `activitytime` datetime DEFAULT NULL COMMENT '活动时间(datetime)',
  `year` year DEFAULT NULL COMMENT '年',
  `times` time DEFAULT NULL COMMENT '时间',
  `refreshtime` bigint DEFAULT NULL COMMENT '刷新时间',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  `deletetime` bigint DEFAULT NULL COMMENT '删除时间',
  `weigh` int DEFAULT '0' COMMENT '权重',
  `switch` tinyint(1) DEFAULT '0' COMMENT '开关',
  `status` enum('normal','hidden') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'normal' COMMENT '状态',
  `state` enum('0','1','2') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '1' COMMENT '状态值:0=禁用,1=正常,2=推荐',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='测试表';


DROP TABLE IF EXISTS `fa_trader`;
CREATE TABLE `fa_trader` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '交易员名称',
  `avatar` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '头像',
  `country` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '国家/地区',
  `roi_rate` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '30日收益率(%)',
  `win_rate` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '胜率(%)',
  `followers` int unsigned NOT NULL DEFAULT '0' COMMENT '跟随人数',
  `total_profit` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '累计收益',
  `min_amount` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '最低跟单金额',
  `intro` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '简介',
  `weigh` int NOT NULL DEFAULT '0' COMMENT '权重',
  `status` enum('normal','hidden') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'normal' COMMENT '状态',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='交易员表';


DROP TABLE IF EXISTS `fa_transaction`;
CREATE TABLE `fa_transaction` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `sn` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '流水单号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `type` enum('deposit','withdraw','transfer','exchange') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'deposit' COMMENT '类型:deposit=充值,withdraw=提现,transfer=划转,exchange=货币兑换',
  `method` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'bank' COMMENT '渠道:bank=银行卡,btc=比特币,eth=以太坊,usdt=USDT,internal=站内划转',
  `currency` varchar(10) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'JPY' COMMENT '币种',
  `amount` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '金额',
  `fee` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '手续费',
  `bank_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '银行名称',
  `branch_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支行名称',
  `account_no` varchar(50) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '账号/钱包地址',
  `account_name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '户名',
  `address` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '链上地址',
  `txid` varchar(128) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '交易哈希',
  `to_user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '收款会员ID(划转)',
  `status` enum('pending','success','rejected') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT '状态:pending=待审核,success=成功,rejected=已驳回',
  `remark` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `checkremark` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核备注',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  `checktime` bigint DEFAULT NULL COMMENT '审核时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sn` (`sn`),
  KEY `idx_user_type` (`user_id`,`type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='资金流水表';


DROP TABLE IF EXISTS `fa_user`;
CREATE TABLE `fa_user` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `group_id` int unsigned NOT NULL DEFAULT '0' COMMENT '组别ID',
  `username` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '用户名',
  `nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '昵称',
  `password` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '密码',
  `salt` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '密码盐',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '电子邮箱',
  `mobile` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '手机号',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '头像',
  `level` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '等级',
  `gender` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '性别',
  `birthday` date DEFAULT NULL COMMENT '生日',
  `bio` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '格言',
  `money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '余额',
  `score` int NOT NULL DEFAULT '0' COMMENT '积分',
  `successions` int unsigned NOT NULL DEFAULT '1' COMMENT '连续登录天数',
  `maxsuccessions` int unsigned NOT NULL DEFAULT '1' COMMENT '最大连续登录天数',
  `prevtime` bigint DEFAULT NULL COMMENT '上次登录时间',
  `logintime` bigint DEFAULT NULL COMMENT '登录时间',
  `loginip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '登录IP',
  `loginfailure` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '失败次数',
  `loginfailuretime` bigint DEFAULT NULL COMMENT '最后登录失败时间',
  `joinip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '加入IP',
  `jointime` bigint DEFAULT NULL COMMENT '加入时间',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  `token` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT 'Token',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '状态',
  `verification` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '验证',
  `pay_password` varchar(32) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '资金密码',
  `pay_salt` varchar(30) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '资金密码盐',
  `kyc_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '实名状态:0=未认证,1=审核中,2=已认证,3=已驳回',
  PRIMARY KEY (`id`),
  KEY `username` (`username`),
  KEY `email` (`email`),
  KEY `mobile` (`mobile`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='会员表';


DROP TABLE IF EXISTS `fa_user_group`;
CREATE TABLE `fa_user_group` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '组名',
  `rules` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '权限节点',
  `createtime` bigint DEFAULT NULL COMMENT '添加时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  `status` enum('normal','hidden') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '状态',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='会员组表';


DROP TABLE IF EXISTS `fa_user_money_log`;
CREATE TABLE `fa_user_money_log` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `admin_id` int unsigned NOT NULL DEFAULT '0' COMMENT '操作管理员ID',
  `money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '变更余额',
  `before` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '变更前余额',
  `after` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '变更后余额',
  `memo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '备注',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='会员余额变动表';


DROP TABLE IF EXISTS `fa_user_rule`;
CREATE TABLE `fa_user_rule` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `pid` int DEFAULT NULL COMMENT '父ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '名称',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '标题',
  `remark` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `ismenu` tinyint(1) DEFAULT NULL COMMENT '是否菜单',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  `weigh` int DEFAULT '0' COMMENT '权重',
  `status` enum('normal','hidden') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '状态',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='会员规则表';


DROP TABLE IF EXISTS `fa_user_score_log`;
CREATE TABLE `fa_user_score_log` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `score` int NOT NULL DEFAULT '0' COMMENT '变更积分',
  `before` int NOT NULL DEFAULT '0' COMMENT '变更前积分',
  `after` int NOT NULL DEFAULT '0' COMMENT '变更后积分',
  `memo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '备注',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='会员积分变动表';


DROP TABLE IF EXISTS `fa_user_token`;
CREATE TABLE `fa_user_token` (
  `token` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Token',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `expiretime` bigint DEFAULT NULL COMMENT '过期时间',
  PRIMARY KEY (`token`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='会员Token表';


DROP TABLE IF EXISTS `fa_user_verify`;
CREATE TABLE `fa_user_verify` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `real_name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '真实姓名',
  `id_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'idcard' COMMENT '证件类型:idcard=身份证,passport=护照,license=驾照',
  `id_number` varchar(50) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证件号码',
  `country` varchar(50) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '日本' COMMENT '国家/地区',
  `front_image` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证件正面',
  `back_image` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证件反面',
  `hand_image` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手持证件',
  `status` enum('pending','pass','reject') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT '状态:pending=待审核,pass=已通过,reject=已驳回',
  `remark` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核备注',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  `checktime` bigint DEFAULT NULL COMMENT '审核时间',
  PRIMARY KEY (`id`),
  KEY `idx_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='实名认证表';


DROP TABLE IF EXISTS `fa_version`;
CREATE TABLE `fa_version` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `oldversion` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '旧版本号',
  `newversion` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '新版本号',
  `packagesize` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '包大小',
  `content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '升级内容',
  `downloadurl` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '下载地址',
  `enforce` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '强制更新',
  `createtime` bigint DEFAULT NULL COMMENT '创建时间',
  `updatetime` bigint DEFAULT NULL COMMENT '更新时间',
  `weigh` int NOT NULL DEFAULT '0' COMMENT '权重',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '状态',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='版本表';


SET FOREIGN_KEY_CHECKS = 1;
